          pattern.append("line")
            .attr("x1", x + size/2)
            .attr("y1", y - size/3)
            .attr("x2", x + size + size/4)
            .attr("y2", y - size/3)
            .attr("stroke", colors.connection)
            .attr("stroke-width", 0.5)
            .attr("opacity", 0.3);
