        letterGroup.append("circle")
          .attr("r", letterRadius)
          .attr("fill", colors.primary)
          .attr("opacity", 0.9);
        
        letterGroup.append("text")
          .attr("text-anchor", "middle")
          .attr("dy", "0.3em")
          .attr("fill", "white")
